-- Estrutura do banco Game GB (42 tabelas, 40 FKs).
-- Convertida do SQL Server (backup banco_teste.bak) para Postgres.
-- Banco limpo: nenhum dado do sistema antigo e importado.
-- Nomes = nomes originais em minusculas, sem aspas (FuncionarioID -> funcionarioid).
-- Chaves primarias: integer GENERATED BY DEFAULT AS IDENTITY, comecando em 1.
-- Referencia: docs/DICIONARIO_BANCO.md

-- As 4 tabelas de teste criadas pelo Lovable sao substituidas pela estrutura real.
DROP TABLE IF EXISTS public.entregas CASCADE;
DROP TABLE IF EXISTS public.tarefas_atribuidas CASCADE;
DROP TABLE IF EXISTS public.tarefas CASCADE;
DROP TABLE IF EXISTS public.funcionarios CASCADE;

-- ---------------------------------------------------------------------------
-- Tabelas sem dependencias
-- ---------------------------------------------------------------------------

CREATE TABLE public.posicoesloja (
  posicaoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nomeposicao varchar(100) NOT NULL,
  coordx double precision NOT NULL,
  coordy double precision NOT NULL,
  ativo boolean DEFAULT true,
  setor varchar(50)
);

CREATE TABLE public.categoriasproduto (
  categoriaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nomecategoria varchar(100) NOT NULL
);

CREATE TABLE public.configuracoesescala (
  configid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  maxhorassempausa integer NOT NULL,
  duracaointervalo integer NOT NULL,
  dataatualizacao timestamptz DEFAULT now(),
  duracaojornadapadrao numeric(10,2)
);

CREATE TABLE public.configuracoessetores (
  setor varchar(50) NOT NULL,
  descricaopadrao text
);

CREATE TABLE public.conquistas (
  conquistaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome varchar(100) NOT NULL,
  descricao varchar(255) NOT NULL,
  icone varchar(10),
  criteriotipo varchar(50) NOT NULL,
  criteriovalor integer NOT NULL,
  pontosbonus integer DEFAULT 0
);

CREATE TABLE public.denunciasanonimas (
  denunciaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  mensagem text NOT NULL,
  dataregistro timestamptz DEFAULT now(),
  status varchar(50) DEFAULT 'Pendente'
);

CREATE TABLE public.fornecedores (
  fornecedorid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cnpj varchar(18) NOT NULL,
  nomefantasia varchar(255) NOT NULL
);

CREATE TABLE public.freelancers (
  freelancerid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome varchar(100) NOT NULL,
  telefone varchar(20),
  habilidadeprincipal varchar(100)
);

CREATE TABLE public.grupos (
  grupoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nomegrupo varchar(100) NOT NULL,
  chatidtelegram varchar(50)
);

CREATE TABLE public.lucromensalhistorico (
  historicoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ano integer NOT NULL,
  mes integer NOT NULL,
  percentuallucro numeric(5,2) NOT NULL,
  dataregistro timestamptz DEFAULT now()
);

CREATE TABLE public.metasdiariasinstancias (
  metainstanciaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  metamodeloid integer,
  data date NOT NULL,
  valormeta numeric(10,2) NOT NULL,
  valoratingido numeric(10,2),
  status varchar(20) DEFAULT 'Pendente'
);

CREATE TABLE public.metasdiariasmodelos (
  diasemanaid integer NOT NULL,
  nomedia varchar(50) NOT NULL,
  valormeta numeric(18,2) NOT NULL,
  pontospremio integer NOT NULL
);

CREATE TABLE public.metasprincipais (
  metaprincipalid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nomemeta varchar(200) NOT NULL,
  descricao text,
  valormetatotal numeric(18,2) NOT NULL,
  datainicio date NOT NULL,
  datafim date NOT NULL,
  pontospremio integer NOT NULL,
  setoralvo varchar(100),
  status varchar(50) DEFAULT 'Ativa'
);

CREATE TABLE public.picodiario (
  diasemanaid integer NOT NULL,
  nomedia varchar(20) NOT NULL,
  horabloqueioinicio time,
  horabloqueiofim time
);

CREATE TABLE public.produtosestoque (
  produtoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nomeproduto varchar(255) NOT NULL,
  unidademedida varchar(10) NOT NULL,
  estoqueminimo numeric(10,3) DEFAULT 0,
  categoria varchar(100) DEFAULT 'Geral'
);

CREATE TABLE public.produtosloja (
  produtoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome varchar(150) NOT NULL,
  descricao text,
  custoempontos integer NOT NULL,
  estoquedisponivel integer,
  ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE public.tarefas (
  tarefaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  titulo varchar(255) NOT NULL,
  descricao text,
  pontos integer NOT NULL,
  datacriacao timestamptz DEFAULT now(),
  ativa boolean DEFAULT true,
  setor varchar(100)
);

CREATE TABLE public.usuariosadmin (
  usuarioid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  login varchar(50) NOT NULL,
  senhahash varchar(64) NOT NULL,
  nomeexibicao varchar(100),
  nivelacesso integer DEFAULT 1
);

-- ---------------------------------------------------------------------------
-- Funcionarios e dependentes
-- ---------------------------------------------------------------------------

CREATE TABLE public.funcionarios (
  funcionarioid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nomecompleto varchar(255) NOT NULL,
  chatidtelegram varchar(100),
  cargo varchar(100),
  pontostotal integer DEFAULT 0,
  horarionotificacao time DEFAULT '08:00',
  diadefolga integer NOT NULL DEFAULT 0,
  saldopontos integer NOT NULL DEFAULT 0,
  verificadorcpf varchar(3),
  senhahash varchar(256),
  isgestor boolean DEFAULT false,
  posicaopadraoid integer REFERENCES public.posicoesloja(posicaoid),
  nivelacesso varchar(50) DEFAULT 'Funcionario',
  cpf varchar(14),
  telefonewhatsapp varchar(20),
  setor varchar(50),
  domingofolgamensal integer DEFAULT 0,
  datainicioafastamento date,
  datafimafastamento date
);

CREATE TABLE public.agendamentos (
  agendamentoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nomecliente varchar(200) NOT NULL,
  cpfcliente varchar(20),
  telefonecliente varchar(50),
  tipoevento varchar(100) NOT NULL,
  dataevento timestamptz NOT NULL,
  statusagendamento varchar(50) NOT NULL DEFAULT 'Confirmado',
  statuspagamento varchar(50) NOT NULL DEFAULT 'Pendente',
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  observacoes text,
  datacriacao timestamptz NOT NULL DEFAULT now(),
  msgcriacaoenviada integer DEFAULT 0,
  msgconfirmacaoenviada integer DEFAULT 0,
  msgposvendaenviada integer DEFAULT 0
);

CREATE TABLE public.conquistasfuncionarios (
  conquistafuncionarioid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  conquistaid integer NOT NULL REFERENCES public.conquistas(conquistaid),
  dataconquista timestamptz DEFAULT now()
);

CREATE TABLE public.contagensestoque (
  contagemid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  datacontagem date NOT NULL,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  dataregistro timestamptz DEFAULT now(),
  nomecontagem varchar(100) DEFAULT 'Geral'
);

CREATE TABLE public.documentos (
  documentoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  titulo varchar(255) NOT NULL,
  conteudo text NOT NULL,
  pontosporciencia integer NOT NULL DEFAULT 0,
  datacriacao timestamptz DEFAULT now(),
  funcionariocriadorid integer REFERENCES public.funcionarios(funcionarioid),
  telegramfileidfoto varchar(255)
);

CREATE TABLE public.documentosassinaturas (
  assinaturaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  documentoid integer NOT NULL REFERENCES public.documentos(documentoid),
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  statusassinatura varchar(50) NOT NULL DEFAULT 'Pendente',
  dataenvio timestamptz DEFAULT now(),
  dataciencia timestamptz
);

CREATE TABLE public.documentospessoais (
  documentoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  tipodocumento varchar(100) NOT NULL,
  mesano date NOT NULL,
  caminhoarquivo varchar(500) NOT NULL,
  dataupload timestamptz DEFAULT now()
);

CREATE TABLE public.documentospessoaisciencia (
  cienciaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  documentoid integer NOT NULL REFERENCES public.documentospessoais(documentoid),
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  status varchar(50) NOT NULL DEFAULT 'Pendente',
  dataenvio timestamptz,
  dataciencia timestamptz
);

CREATE TABLE public.entregas (
  entregaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tarefaid integer NOT NULL REFERENCES public.tarefas(tarefaid),
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  dataenvio timestamptz DEFAULT now(),
  pathfotoevidencia varchar(255),
  statusvalidacao varchar(50) DEFAULT 'Pendente',
  pontosganhos integer DEFAULT 0,
  motivorecusa text,
  atribuicaoid integer,
  fileidtelegram varchar(255),
  notificacaogestorenviada boolean DEFAULT false
);

CREATE TABLE public.escaladiaria (
  escalaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  dataescala date NOT NULL,
  posicaoid integer NOT NULL REFERENCES public.posicoesloja(posicaoid),
  funcionarioid integer REFERENCES public.funcionarios(funcionarioid),
  freelancerid integer REFERENCES public.freelancers(freelancerid),
  horarioentrada time,
  horariosaida time,
  iniciointervalo time,
  fimintervalo time,
  focododia text,
  statusconfirmacao varchar(20) DEFAULT 'Pendente'
);

CREATE TABLE public.feedbacks (
  feedbackid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  datafeedback date NOT NULL,
  notadia integer NOT NULL,
  comentario varchar(500)
);

CREATE TABLE public.feedbacksolicitacoes (
  solicitacaoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  datasolicitacao timestamptz NOT NULL DEFAULT now(),
  textoassunto text NOT NULL,
  status varchar(50) NOT NULL DEFAULT 'Pendente',
  dataresposta timestamptz,
  textoresposta text
);

CREATE TABLE public.funcionariosgrupos (
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  grupoid integer NOT NULL REFERENCES public.grupos(grupoid)
);

CREATE TABLE public.historicoranking (
  historicoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ano integer NOT NULL,
  mes integer NOT NULL,
  posicao integer NOT NULL,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  nomefuncionario varchar(255) NOT NULL,
  pontosganhos integer NOT NULL,
  pontospossiveis integer NOT NULL,
  percentualdesempenho numeric(5,2) NOT NULL
);

CREATE TABLE public.itenscontagemestoque (
  itemcontagemid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  contagemid integer NOT NULL REFERENCES public.contagensestoque(contagemid),
  produtoid integer REFERENCES public.produtosestoque(produtoid),
  quantidadecontada numeric(10,3) NOT NULL,
  nomeavulso varchar(255),
  eanavulso varchar(50)
);

CREATE TABLE public.notasfiscaisentrada (
  notaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  numeronf varchar(50) NOT NULL,
  fornecedorid integer NOT NULL REFERENCES public.fornecedores(fornecedorid),
  dataemissao date NOT NULL,
  valortotalnf numeric(10,2) NOT NULL,
  dataimportacao timestamptz DEFAULT now()
);

CREATE TABLE public.produtosfornecedor (
  produtofornecedorid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  produtoid integer NOT NULL REFERENCES public.produtosestoque(produtoid),
  fornecedorid integer NOT NULL REFERENCES public.fornecedores(fornecedorid),
  descricaoxml varchar(255) NOT NULL,
  datacriacao timestamptz DEFAULT now(),
  codigofornecedor varchar(60),
  ean varchar(14),
  ncm varchar(20),
  fatorconversao numeric(10,4) DEFAULT 1.0
);

CREATE TABLE public.itensnotafiscalentrada (
  itemnotaid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  notaid integer NOT NULL REFERENCES public.notasfiscaisentrada(notaid),
  produtofornecedorid integer NOT NULL REFERENCES public.produtosfornecedor(produtofornecedorid),
  quantidade numeric(10,3) NOT NULL,
  precocustounitario numeric(10,4) NOT NULL
);

CREATE TABLE public.metasdiariasapuracoes (
  apuracaoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  metaprincipalid integer REFERENCES public.metasprincipais(metaprincipalid),
  dataapuracao date NOT NULL,
  valordia numeric(18,2) NOT NULL,
  funcionarioid_lancamento integer REFERENCES public.funcionarios(funcionarioid),
  pontosmetadiariaganhos integer DEFAULT 0
);

CREATE TABLE public.notasfiscais (
  notafiscalid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  fileidtelegram varchar(255) NOT NULL,
  pathfoto varchar(512),
  status varchar(50) DEFAULT 'Pendente',
  datarecebimento timestamptz DEFAULT now()
);

CREATE TABLE public.onboardingstatus (
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  statusworkflow varchar(50) NOT NULL DEFAULT 'Pendente',
  ultimaetapa varchar(100),
  escolaridade varchar(50),
  estadocivil varchar(50),
  qtdfilhos integer DEFAULT 0,
  dadosfilhos text,
  rg_fileid varchar(255),
  cpf_fileid varchar(255),
  ctps_fileid varchar(255),
  tituloeleitor_fileid varchar(255),
  datacasamento varchar(10),
  nomeconjugue varchar(100),
  cpfconjugue varchar(14),
  dataadmissional timestamptz,
  statusadmissional varchar(50) NOT NULL DEFAULT 'Pendente'
);

CREATE TABLE public.resgates (
  resgateid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionarioid integer NOT NULL REFERENCES public.funcionarios(funcionarioid),
  produtoid integer NOT NULL REFERENCES public.produtosloja(produtoid),
  pontosgastos integer NOT NULL,
  datasolicitacao timestamptz NOT NULL DEFAULT now(),
  status varchar(50) NOT NULL DEFAULT 'Pendente',
  gestorid_aprovacao integer,
  dataaprovacao timestamptz
);

CREATE TABLE public.solicitacoesinternas (
  solicitacaoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  funcionarioid integer REFERENCES public.funcionarios(funcionarioid),
  datasolicitacao timestamptz DEFAULT now(),
  tipo varchar(20) NOT NULL,
  categoria varchar(50),
  descricao text,
  quantidade numeric(10,2),
  caminhofoto varchar(255),
  status varchar(20) DEFAULT 'Pendente',
  motivorecusa text,
  dataconclusao timestamptz
);

CREATE TABLE public.tarefasatribuidas (
  atribuicaoid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tarefaid integer NOT NULL REFERENCES public.tarefas(tarefaid),
  funcionarioid integer REFERENCES public.funcionarios(funcionarioid),
  dataatribuicao timestamptz DEFAULT now(),
  tipofrequencia varchar(20) NOT NULL DEFAULT 'Unica',
  valorfrequencia integer,
  grupoid integer REFERENCES public.grupos(grupoid),
  funcionarioresponsavelid integer REFERENCES public.funcionarios(funcionarioid),
  horariodisparo time,
  statustarefagrupo varchar(50),
  dataaceite timestamptz,
  datainiciovigencia date,
  datafimvigencia date,
  agendamentoid integer,
  dataagendamento timestamptz,
  descricaooverride text,
  origematribuicaoid integer REFERENCES public.tarefasatribuidas(atribuicaoid)
);

