GRANT SELECT, INSERT, UPDATE, DELETE ON public.posicoesloja TO authenticated;
GRANT ALL ON public.posicoesloja TO service_role;
ALTER TABLE public.posicoesloja ENABLE ROW LEVEL SECURITY;
